def rendu(somme, pieces):
    rendues = []
    i = 0
    while somme > 0:
        if pieces[i] <= somme:
            rendues.append(pieces[i])
            somme = somme - pieces[i]
        else:
            i = i + 1
    return rendues

assert rendu(263, [200, 100, 50, 20, 10, 5, 2, 1]) == [200, 50, 10, 2, 1]
```

