def fin(a):
    return a[1]

def planning(activites):
    retenues = []
    for a in sorted(activites, key=fin):
        if retenues == [] or a[0] >= retenues[-1][1]:
            retenues.append(a)
    return retenues

assert planning([(9, 12), (8, 10), (10, 11), (11, 13)]) == [(8, 10), (10, 11), (11, 13)]
assert planning([]) == []
```
